            if current_row or (i > 0 and text[i-1] in (delimiter, '\n', '\r')):
                 # Eğer metin bir ayırıcı ile bittiyse, bir boş alan daha eklenmeli
                if text[-1] == delimiter:
                    current_row.append("")
                results.append(current_row)

    return results
